def merge_intervals(iv: list) -> list:
    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # Sort intervals by start
    sorted_iv = sorted(iv, key=lambda x: x[0])
    merged = [sorted_iv[0]]
    for curr in sorted_iv[1:]:
        last = merged[-1]
        # If current interval starts before or at the end of last, merge
        if curr[0] <= last[1]:
            last[1] = max(last[1], curr[1])
        else:
            merged.append(curr)
    return merged

def days_between(a: str, b: str) -> int:
    """Number of days from ISO date a to ISO date b (b - a)."""
    from datetime import datetime
    fmt = "%Y-%m-%d"
    try:
        da = datetime.strptime(a, fmt).date()
        db = datetime.strptime(b, fmt).date()
    except Exception as e:
        raise ValueError(f"Invalid ISO date format: {e}")
    return (db - da).days

